     * 关闭页面并跳转
     */
    cancelEvent: function cancelEvent() {
      this.$router.push('/xcnanr/ideal/repairPlan/index');
    },
    /**
     * 选择事件
     * @param selection
     */
    selectionChange: function selectionChange(selection) {
      this.selectionList = selection.map(function (item) {
        return item.id;
      });
    }
  }
};
